const $=s=>document.querySelector(s),key='songbing-keepsake-v1';
const initial=()=>({version:1,cover:'',memories:[],photos:[],wishes:['一起看日落','交换一本书','去一次徒步','做一顿饭','拍一组合照'].map((title,i)=>({id:'idea'+i,title,idea:true,done:false,date:'',image:''})),letters:{bingxue:'',songsong:''},meeting:{date:'',city:'',text:''}});
let state=initial();try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&valid(saved))state=saved}catch(e){}
function valid(s){return s&&s.version===1&&typeof s.cover==='string'&&['memories','photos','wishes'].every(k=>Array.isArray(s[k])&&s[k].every(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&(!x.image||/^data:image\/(jpeg|png|webp);base64,/.test(x.image))))&&s.letters&&typeof s.letters.bingxue==='string'&&typeof s.letters.songsong==='string'&&s.meeting&&typeof s.meeting.date==='string'}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),2800)}
function persist(next){try{localStorage.setItem(key,JSON.stringify(next));state=next;render();return true}catch(e){toast('保存失败：浏览器空间不足或禁用存储。请先导出备份、减少照片。');return false}}
function esc(t=''){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function imageTag(src,alt=''){return /^data:image\/(jpeg|png|webp);base64,/.test(src||'')?`<img src="${esc(src)}" alt="${esc(alt)}">`:''}
function render(){if(state.cover)$('#cover').innerHTML=imageTag(state.cover,'你们上传的合照');$('#memoryList').innerHTML=state.memories.length?state.memories.slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')).map(m=>`<article class="memory"><button class="edit" data-edit="memory" data-id="${esc(m.id)}">编辑</button><small>${esc(m.date||'日期待填写')} · ${esc(m.author||'一起记录')} ${m.city?' / '+esc(m.city):''}</small><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p>${m.image?`<button data-memory-photo="${esc(m.id)}" aria-label="放大回忆照片">${imageTag(m.image,m.title)}</button>`:''}</article>`).join(''):'<div class="empty-memory"><small>日期待填写 / 一起记录</small><h3>第一段回忆，等你们写下</h3><p>记一个日期、一处地方，或某个平凡的小瞬间。</p><button data-new="memory">开始记录 ↗</button></div>';
$('#photoList').innerHTML=state.photos.length?state.photos.map(p=>`<article class="photo-card"><button data-view="${esc(p.id)}">${imageTag(p.image,p.title)}<p>${esc(p.title||'说明待填写')}</p><time>${esc(p.date||'日期待填写')}</time></button></article>`).join(''):[1,2,3].map((n)=>`<article class="photo-card"><button data-new="photo"><div class="photo-placeholder">＋<small>留给我们的第 ${n} 张照片</small></div><p>这一页，等待你们的画面</p><time>照片与日期待添加</time></button></article>`).join('');
$('#wishList').innerHTML=state.wishes.length?state.wishes.map(w=>`<div class="wish ${w.done?'done':''}"><input type="checkbox" id="wish-${esc(w.id)}" data-check="${esc(w.id)}" ${w.done?'checked':''}><label for="wish-${esc(w.id)}"><span>${esc(w.title)}</span><small>${w.idea?'灵感建议 · ':''}${w.done?'已完成'+(w.date?' · '+esc(w.date):' · 日期可补充'):'慢慢来就好'}</small></label><button data-edit="wish" data-id="${esc(w.id)}" aria-label="编辑愿望 ${esc(w.title)}">编辑 ↗</button></div>`).join(''):'<p class="hint">愿望清单空着也没关系。想到了，再写下来。</p>';
const m=state.meeting;if(m.date){const target=new Date(m.date+'T00:00:00+08:00'),now=new Date(),today=new Date(now.toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'})+'T00:00:00+08:00');const days=Math.round((target-today)/86400000);$('#meetingTitle').textContent=days>0?`距离下一次见面，还有 ${days} 天`:days===0?'今天，是约定见面的日子':'这一页计划，等你们更新';$('#meetingText').textContent=[m.date,m.city,m.text].filter(Boolean).join(' · ')}else{$('#meetingTitle').textContent='一起安排下一次见面';$('#meetingText').textContent=[m.city,m.text].filter(Boolean).join(' · ')||'把日历里的某一天，留给我们。'}}
let context=null;function field(name,label,type='text',value='',placeholder=''){return `<label class="field">${label}${type==='textarea'?`<textarea name="${name}" placeholder="${placeholder}">${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${type==='file'?'':esc(value)}" ${type==='file'?'accept="image/jpeg,image/png,image/webp"':''} placeholder="${placeholder}">`}</label>`}
function openEdit(type,id){let obj={},title='',html='';if(['memory','photo','wish'].includes(type)){obj=state[type==='memory'?'memories':type==='photo'?'photos':'wishes'].find(x=>x.id===id)||{};title=type==='memory'?'写下一段回忆':type==='photo'?'收藏一张照片':'想一起完成的事';html=field('title',type==='photo'?'一句话说明（可留空）':'标题','text',obj.title||'','在这里写下…')+field('date',type==='wish'?'完成日期（选填）':'日期（选填）','date',obj.date||'');if(type==='memory')html+=field('city','地点（选填）','text',obj.city||'','城市或地点，无需具体住址')+`<label class="field">由谁写下<select name="author">${['一起记录','松松写下','冰雪写下'].map(a=>`<option ${obj.author===a?'selected':''}>${a}</option>`).join('')}</select></label>`+field('text','这一天的小事','textarea',obj.text||'','想记住的细节，由你们亲自写下。');if(type==='wish')html+=`<label class="field"><input type="checkbox" name="done" ${obj.done?'checked':''}> 已经一起完成了</label>`;html+=field('image',type==='wish'?'完成照片（选填）':'照片'+(type==='photo'?'（必填）':'（选填）'),'file');if(obj.image)html+='<p class="hint">已有照片。不选择新照片会保留原图。</p><label><input type="checkbox" name="removeImage"> 移除原照片</label>'}
if(type==='cover'){title='放一张我们的合照';html=field('image','选择合照','file')+'<p>没有照片也没关系，这一页会继续等你们。</p>'}
if(type==='meeting'){title='下一次见面';obj=state.meeting;html=field('date','见面日期（选填）','date',obj.date)+field('city','城市（选填）','text',obj.city,'例如：上海 / 南京')+field('text','想一起做的事情','textarea',obj.text,'留一点期待，也留一点随意。')}
if(type==='bingxue'||type==='songsong'){title=type==='bingxue'?'写给冰雪':'写给松松';html=field('text','你想说的话','textarea',state.letters[type],'写作提示：最近的一件小事、想分享的心情，或一句还没来得及说的话。')}
context={type,id,obj};$('#formTitle').textContent=title;$('#fields').innerHTML=html;$('#deleteItem').hidden=!obj.id;$('#editor').showModal()}
async function compress(file){if(!file)return '';if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('请选择 JPG、PNG 或 WebP 图片');if(file.size>25*1024*1024)throw Error('图片超过 25MB，请先缩小');const img=new Image(),url=URL.createObjectURL(file);try{await new Promise((res,rej)=>{img.onload=res;img.onerror=()=>rej(Error('图片无法读取'));img.src=url});const ratio=Math.min(1,1400/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.78)}finally{URL.revokeObjectURL(url)}}
$('#editForm').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;submit.disabled=true;try{const f=new FormData(e.target),{type,id,obj}=context,next=structuredClone(state),file=f.get('image');let img=file&&file.size?await compress(file):obj.image||'';if(f.get('removeImage'))img='';if(['memory','photo','wish'].includes(type)){const title=String(f.get('title')||'').trim();if(type!=='photo'&&!title)throw Error('请填写标题');if(type==='photo'&&!img)throw Error('请先选择照片');const item={...obj,id:id||crypto.randomUUID(),title,date:String(f.get('date')||''),image:img};if(type==='memory')Object.assign(item,{city:String(f.get('city')||''),text:String(f.get('text')||''),author:String(f.get('author'))});if(type==='wish')Object.assign(item,{done:!!f.get('done'),idea:false});const list=next[type==='memory'?'memories':type==='photo'?'photos':'wishes'],index=list.findIndex(x=>x.id===id);index<0?list.push(item):list.splice(index,1,item)}else if(type==='cover'){if(!img)throw Error('请先选择照片');next.cover=img}else if(type==='meeting')next.meeting={date:String(f.get('date')),city:String(f.get('city')),text:String(f.get('text'))};else next.letters[type]=String(f.get('text'));if(persist(next)){$('#editor').close();toast('已保存在当前设备')}}catch(err){toast(err.message)}finally{submit.disabled=false}};
$('#deleteItem').onclick=()=>{if(!confirm('确定删除这条记录吗？此操作无法撤销。'))return;const next=structuredClone(state),{type,id}=context,k=type==='memory'?'memories':type==='photo'?'photos':'wishes';next[k]=next[k].filter(x=>x.id!==id);if(persist(next)){$('#editor').close();toast('已删除')}};
function view(src,title,date,id){$('#largePhoto').src=src;$('#largePhoto').alt=title||'收藏的照片';$('#largeCaption').textContent=[title,date].filter(Boolean).join(' · ');$('#editPhoto').hidden=!id;$('#editPhoto').onclick=()=>{$('#lightbox').close();openEdit('photo',id)};$('#lightbox').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-new],[data-edit],[data-letter],[data-view],[data-memory-photo]');if(!b)return;if(b.dataset.new)openEdit(b.dataset.new);if(b.dataset.edit)openEdit(b.dataset.edit,b.dataset.id);if(b.dataset.letter)openEdit(b.dataset.letter);if(b.dataset.view){const p=state.photos.find(x=>x.id===b.dataset.view);view(p.image,p.title,p.date,p.id)}if(b.dataset.memoryPhoto){const p=state.memories.find(x=>x.id===b.dataset.memoryPhoto);view(p.image,p.title,p.date)}});
document.addEventListener('change',e=>{if(e.target.dataset.check){const next=structuredClone(state);next.wishes.find(x=>x.id===e.target.dataset.check).done=e.target.checked;if(persist(next))toast('愿望已保存；可在编辑中补充完成日期和照片')}});
$('#coverEdit').onclick=()=>openEdit('cover');$('#meetingEdit').onclick=()=>openEdit('meeting');$('#closeEditor').onclick=()=>$('#editor').close();$('#closeLightbox').onclick=()=>$('#lightbox').close();$('#settings').onclick=$('#backup').onclick=()=>$('#dataDialog').showModal();$('#closeData').onclick=()=>$('#dataDialog').close();$('#exportData').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='松松与冰雪-手记备份.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出，请妥善保存')};$('#importData').onclick=()=>$('#importFile').click();$('#importFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>30*1024*1024)throw Error('备份文件过大');const next=JSON.parse(await file.text());if(!valid(next))throw Error('不是有效的手记备份文件');if(confirm('导入将替换当前全部内容。建议先导出当前备份，是否继续？'))if(persist(next))toast('导入成功')}catch(err){toast('导入失败：'+err.message)}finally{e.target.value=''}};render();
